<?php $filter_action=base_url('weighted_exam/processing');$this->load->view('weighted_exam/_filters',get_defined_vars());?>
<?php if($examId&&$classId&&$sectionId):?><?=form_open('weighted_exam/processing')?><?php foreach(['exam_id'=>$examId,'class_id'=>$classId,'section_id'=>$sectionId] as $k=>$v):?><input type="hidden" name="<?=$k?>" value="<?=$v?>"><?php endforeach?><section class="panel"><header class="panel-heading"><h4 class="panel-title">Preview and Finalize Results</h4></header><div class="panel-body"><p>Preview validates every applicable component. Finalization is blocked if any included subject is incomplete.</p><?php if($rows):?><div class="table-responsive"><table class="table table-bordered"><thead><tr><th>Roll</th><th>Student</th><th>Included Subjects</th><th>Total</th><th>Percentage</th><th>Category</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['student']['roll']?></td><td><?=html_escape($r['student']['student_name'])?></td><td><?=$r['overall']['subject_count']?></td><td><?=number_format($r['overall']['total'],2)?></td><td><?=$r['overall']['display_percentage']?:'—'?></td><td><?=html_escape($r['grade']?$r['grade']['name']:'No matching rule')?></td><td><?=ucfirst($r['result_status'])?></td></tr><?php endforeach?></tbody></table></div><?php endif?></div><footer class="panel-footer text-right"><button name="process" value="preview" class="btn btn-default"><i class="fas fa-calculator"></i> Preview Results</button> <button name="process" value="finalize" class="btn btn-success" onclick="return confirm('Finalize and lock these results?')"><i class="fas fa-lock"></i> Finalize Results</button></footer></section><?=form_close()?><?php endif?>

